import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'

    # Tally counts in one pass
    opp_c = 0
    opp_d = 0
    my_c = 0
    my_d = 0
    for i in range(n):
        a, b = history[i]
        if a == 'C':
            my_c += 1
        else:
            my_d += 1
        if b == 'C':
            opp_c += 1
        else:
            opp_d += 1

    opp_rate = opp_c / n
    last_my, last_opp = history[-1]

    # Opponent run length (consecutive same action at end)
    run_o = 1
    i = n - 1
    while i > 0 and history[i - 1][1] == last_opp:
        run_o += 1
        i -= 1

    run_m = 1
    j = n - 1
    while j > 0 and history[j - 1][0] == last_my:
        run_m += 1
        j -= 1

    rounds_left = 100 - n

    # ---- Identify pure strategies ----

    # Always-cooperator: exploit, but max out in the endgame.
    if opp_d == 0:
        if n >= 4:
            if rounds_left <= 3:
                return 'D'
            if run_m >= 6:
                return 'D'
            return 'D' if rng.random() < 0.85 else 'C'
        return 'C'

    # Always-defector: defect back (no point feeding them).
    if opp_c == 0:
        return 'D'

    # ---- Endgame: defect unless opponent is a confirmed cooperator ----
    if rounds_left <= 2:
        return 'D'

    # ---- Cooperative-but-not-pure opponent ----
    if opp_rate >= 0.85:
        # Forgive isolated defections (likely noise/exploration).
        if last_opp == 'D':
            if run_o >= 2:
                return 'D'
            return 'C'
        # Mostly cooperate, occasional probe if we've been clean.
        if run_m >= 5 and rounds_left > 15 and rng.random() < 0.12:
            return 'D'
        return 'C'

    # ---- Highly exploitative opponent ----
    if opp_rate <= 0.2:
        # Their rare C's shouldn't be met with our C's often.
        if last_opp == 'C':
            # Reward briefly to see if they turn, but limit.
            if run_o >= 1 and rng.random() < 0.4:
                return 'C'
            return 'D'
        return 'D'

    # ---- Moderate opponent (mixed) ----

    # Escalating-punisher response: if they gave us 2 D's in a row, punish.
    if run_o >= 3:
        if run_m >= 3 and rng.random() < 0.2:
            return 'C'
        return 'D'

    # If we ourselves have been defecting too long, probe back to C.
    if run_m >= 4 and last_opp == 'C':
        return 'C'
    if run_m >= 5:
        return 'C' if rng.random() < 0.4 else 'D'

    # Last opponent action matters most for mixed opponents
    if last_opp == 'D':
        # Active exploitation: if they consistently cash in on our C's,
        # don't over-forgive.
        if opp_rate >= 0.5:
            # They cooperate enough that one D might be noise; forgive once.
            if run_o == 1 and run_m >= 3:
                return 'C'
            return 'D'
        # Below-average cooperator: mostly defect.
        return 'D' if rng.random() < 0.85 else 'C'

    # Opponent just cooperated
    if last_my == 'D':
        # Re-establish cooperation only if they seem receptive.
        if opp_rate >= 0.5:
            return 'C'
        return 'D' if rng.random() < 0.5 else 'C'

    # Both cooperated: mainly cooperate.
    # Slight probe against very cooperative-ish opponents to test for exploiters.
    if opp_rate >= 0.7 and rounds_left > 20 and rng.random() < 0.06:
        return 'D'
    return 'C'
